#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Al-othmany Sender 3.5.5 FINAL ALL-IN-ONE

One upload patch for the Android source repository.
Includes everything from 3.5.4 plus the 3.5.5 compact UI, connection-card,
and structural fast-continuity repair.

Accepted source states: 3.5.0 .. 3.5.5
Final: versionCode 355 / versionName 3.5.5
"""
from pathlib import Path
import base64, re, traceback

ROOT=Path.cwd()
if not (ROOT/'app').is_dir():
    raise SystemExit('ERROR: run from the Android repository root')

BASE354=''
FIX355=''

def run_payload(label,payload):
    print('\n'+'='*74)
    print(label)
    print('='*74)
    src=base64.b64decode(payload).decode('utf-8')
    ns={'__name__':'__main__','__file__':f'<embedded:{label}>'}
    try:
        exec(compile(src,ns['__file__'],'exec'),ns,ns)
    except SystemExit:
        raise
    except Exception:
        traceback.print_exc()
        raise SystemExit(f'ERROR while applying {label}')

def version_code():
    s=(ROOT/'app/build.gradle.kts').read_text(encoding='utf-8')
    m=re.search(r'versionCode\s*=\s*(\d+)',s)
    return int(m.group(1)) if m else -1

vc=version_code()
if vc < 354:
    run_payload('STEP 1/2 - APPLY COMPLETE 3.5.4 BASE',BASE354)
elif vc in (354,355):
    print(f'Source versionCode={vc}; complete 3.5.4 base stage not required.')
else:
    raise SystemExit(f'ERROR: unsupported future versionCode={vc}')

run_payload('STEP 2/2 - APPLY 3.5.5 COMPACT ULTRA-FAST CONTINUITY',FIX355)

build=(ROOT/'app/build.gradle.kts').read_text(encoding='utf-8')
layout=(ROOT/'app/src/main/res/layout/activity_main.xml').read_text(encoding='utf-8')
main=(ROOT/'app/src/main/java/com/althmany/groupmanager/ui/MainActivity.kt').read_text(encoding='utf-8')
acc=(ROOT/'app/src/main/java/com/althmany/groupmanager/accessibility/QuickJoinAccessibilityService.kt').read_text(encoding='utf-8')
sh=(ROOT/'app/src/main/java/com/althmany/groupmanager/shizuku/ShizukuAutomationService.kt').read_text(encoding='utf-8')
required=[
    ('build versionCode','versionCode = 355' in build),
    ('build versionName','versionName = "3.5.5"' in build),
    ('compact UI','android:tag="compact355"' in layout),
    ('Shizuku connect card','exactShizukuConnectCard' in layout and 'exactShizukuConnectCard' in main),
    ('Accessibility connect card','exactAccessibilityConnectCard' in layout and 'exactAccessibilityConnectCard' in main),
    ('MAX smart start','arms the fastest verified profile' in main),
    ('Accessibility request fast exit','repeat(1)' in acc and 'fastExitPendingRequestSurface' in acc),
    ('Shizuku one-back conversation exit','conversation remained after one Back pulse' in sh),
]
missing=[name for name,ok in required if not ok]
if missing:
    raise SystemExit('ERROR: 3.5.5 final sanity failed: '+', '.join(missing))

print('\n'+'='*74)
print('✅ AL-OTHMANY SENDER 3.5.5 FINAL ALL-IN-ONE APPLIED')
print('='*74)
print('Included:')
print(' - smaller exact dashboard')
print(' - working Shizuku / Accessibility connection cards')
print(' - visible controls remain bridged to the real engine')
print(' - Smart Start arms MAX + 0ms artificial inter-link delay')
print(' - fewer redundant Back pulses in fast request/conversation exits')
print(' - shorter exact-user conversation proof grace in Shizuku')
print(' - validated scan/click safety timings retained')
print(' - ~2s best-effort target on responsive normal invite screens')
print('\nRun next:')
print('  python3 scripts/validate_source.py')
print('  bash scripts/compile_pure_kotlin.sh')
print('  bash scripts/run_pure_kotlin_regressions.sh')
print('  gradle --no-daemon --no-configuration-cache :app:assembleDebug --console=plain')
